CREATE TABLE public.contas_financeiras (
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(), clinica_id uuid NOT NULL REFERENCES public.clinicas(id), unidade_id uuid REFERENCES public.unidades(id), nome text NOT NULL, tipo text NOT NULL CHECK(tipo IN ('caixa','banco','carteira_digital')), banco text, agencia text, conta text, saldo_inicial numeric(12,2) NOT NULL DEFAULT 0, ativo boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(clinica_id,nome));
GRANT SELECT,INSERT,UPDATE ON public.contas_financeiras TO authenticated; GRANT ALL ON public.contas_financeiras TO service_role; ALTER TABLE public.contas_financeiras ENABLE ROW LEVEL SECURITY;
CREATE POLICY "contas_fin_select" ON public.contas_financeiras FOR SELECT TO authenticated USING(clinica_id=current_clinica_id() AND tem_papel('owner','admin','financeiro','recepcao'));
CREATE POLICY "contas_fin_write" ON public.contas_financeiras FOR ALL TO authenticated USING(clinica_id=current_clinica_id() AND tem_papel('owner','admin','financeiro')) WITH CHECK(clinica_id=current_clinica_id() AND tem_papel('owner','admin','financeiro'));
CREATE TRIGGER trg_auditar AFTER INSERT OR UPDATE OR DELETE ON public.contas_financeiras FOR EACH ROW EXECUTE FUNCTION public.auditar();

CREATE TABLE public.formas_pagamento (
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(), clinica_id uuid NOT NULL REFERENCES public.clinicas(id), nome text NOT NULL, tipo text NOT NULL CHECK(tipo IN ('dinheiro','pix','debito','credito','boleto','convenio','plano_interno')), taxa_percentual numeric(12,2) NOT NULL DEFAULT 0 CHECK(taxa_percentual BETWEEN 0 AND 100), taxa_fixa numeric(12,2) NOT NULL DEFAULT 0 CHECK(taxa_fixa>=0), prazo_recebimento_dias integer NOT NULL DEFAULT 0 CHECK(prazo_recebimento_dias>=0), parcelamento_maximo integer NOT NULL DEFAULT 1 CHECK(parcelamento_maximo BETWEEN 1 AND 48), taxas_por_parcela jsonb NOT NULL DEFAULT '{}'::jsonb, conta_financeira_id uuid REFERENCES public.contas_financeiras(id), ativo boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(clinica_id,nome));
GRANT SELECT,INSERT,UPDATE ON public.formas_pagamento TO authenticated; GRANT ALL ON public.formas_pagamento TO service_role; ALTER TABLE public.formas_pagamento ENABLE ROW LEVEL SECURITY;
CREATE POLICY "formas_select" ON public.formas_pagamento FOR SELECT TO authenticated USING(clinica_id=current_clinica_id() AND tem_papel('owner','admin','financeiro','recepcao','dentista','esteticista'));
CREATE POLICY "formas_write" ON public.formas_pagamento FOR ALL TO authenticated USING(clinica_id=current_clinica_id() AND tem_papel('owner','admin','financeiro')) WITH CHECK(clinica_id=current_clinica_id() AND tem_papel('owner','admin','financeiro'));
CREATE TRIGGER trg_auditar AFTER INSERT OR UPDATE OR DELETE ON public.formas_pagamento FOR EACH ROW EXECUTE FUNCTION public.auditar();

CREATE TABLE public.centros_custo (
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(), clinica_id uuid NOT NULL REFERENCES public.clinicas(id), unidade_id uuid REFERENCES public.unidades(id), especialidade_id uuid REFERENCES public.especialidades(id), nome text NOT NULL, ativo boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(clinica_id,nome));
GRANT SELECT,INSERT,UPDATE ON public.centros_custo TO authenticated; GRANT ALL ON public.centros_custo TO service_role; ALTER TABLE public.centros_custo ENABLE ROW LEVEL SECURITY;
CREATE POLICY "centros_select" ON public.centros_custo FOR SELECT TO authenticated USING(clinica_id=current_clinica_id() AND tem_papel('owner','admin','financeiro'));
CREATE POLICY "centros_write" ON public.centros_custo FOR ALL TO authenticated USING(clinica_id=current_clinica_id() AND tem_papel('owner','admin','financeiro')) WITH CHECK(clinica_id=current_clinica_id() AND tem_papel('owner','admin','financeiro'));
CREATE TRIGGER trg_auditar AFTER INSERT OR UPDATE OR DELETE ON public.centros_custo FOR EACH ROW EXECUTE FUNCTION public.auditar();

ALTER TABLE public.plano_contas ADD COLUMN IF NOT EXISTS pai_id uuid REFERENCES public.plano_contas(id), ADD COLUMN IF NOT EXISTS codigo text, ADD COLUMN IF NOT EXISTS natureza text CHECK(natureza IN ('receita','deducao','custo_variavel','despesa_fixa','despesa_financeira','investimento')), ADD COLUMN IF NOT EXISTS ativo boolean NOT NULL DEFAULT true;
CREATE UNIQUE INDEX IF NOT EXISTS plano_contas_codigo_unique ON public.plano_contas(clinica_id,codigo) WHERE codigo IS NOT NULL;
COMMENT ON COLUMN public.plano_contas.centro_custo IS 'DEPRECATED: replaced by centro_custo_id on financial entries';

ALTER TABLE public.financeiro_recebimentos ADD COLUMN IF NOT EXISTS competencia date, ADD COLUMN IF NOT EXISTS conta_financeira_id uuid REFERENCES public.contas_financeiras(id), ADD COLUMN IF NOT EXISTS centro_custo_id uuid REFERENCES public.centros_custo(id), ADD COLUMN IF NOT EXISTS forma_pagamento_id uuid REFERENCES public.formas_pagamento(id), ADD COLUMN IF NOT EXISTS valor_bruto numeric(12,2), ADD COLUMN IF NOT EXISTS taxa numeric(12,2) NOT NULL DEFAULT 0, ADD COLUMN IF NOT EXISTS valor_liquido numeric(12,2), ADD COLUMN IF NOT EXISTS juros numeric(12,2) NOT NULL DEFAULT 0, ADD COLUMN IF NOT EXISTS multa numeric(12,2) NOT NULL DEFAULT 0, ADD COLUMN IF NOT EXISTS desconto_baixa numeric(12,2) NOT NULL DEFAULT 0, ADD COLUMN IF NOT EXISTS valor_pago numeric(12,2) NOT NULL DEFAULT 0, ADD COLUMN IF NOT EXISTS previsto_credito_em date, ADD COLUMN IF NOT EXISTS recorrencia_id uuid, ADD COLUMN IF NOT EXISTS comprovante_path text, ADD COLUMN IF NOT EXISTS origem_tipo text, ADD COLUMN IF NOT EXISTS origem_id uuid;
ALTER TABLE public.financeiro_pagamentos ADD COLUMN IF NOT EXISTS competencia date, ADD COLUMN IF NOT EXISTS conta_financeira_id uuid REFERENCES public.contas_financeiras(id), ADD COLUMN IF NOT EXISTS centro_custo_id uuid REFERENCES public.centros_custo(id), ADD COLUMN IF NOT EXISTS forma_pagamento_id uuid REFERENCES public.formas_pagamento(id), ADD COLUMN IF NOT EXISTS valor_bruto numeric(12,2), ADD COLUMN IF NOT EXISTS taxa numeric(12,2) NOT NULL DEFAULT 0, ADD COLUMN IF NOT EXISTS valor_liquido numeric(12,2), ADD COLUMN IF NOT EXISTS juros numeric(12,2) NOT NULL DEFAULT 0, ADD COLUMN IF NOT EXISTS multa numeric(12,2) NOT NULL DEFAULT 0, ADD COLUMN IF NOT EXISTS desconto_baixa numeric(12,2) NOT NULL DEFAULT 0, ADD COLUMN IF NOT EXISTS valor_pago numeric(12,2) NOT NULL DEFAULT 0, ADD COLUMN IF NOT EXISTS previsto_credito_em date, ADD COLUMN IF NOT EXISTS recorrencia_id uuid, ADD COLUMN IF NOT EXISTS comprovante_path text, ADD COLUMN IF NOT EXISTS origem_tipo text, ADD COLUMN IF NOT EXISTS origem_id uuid;
COMMENT ON COLUMN public.financeiro_recebimentos.forma_pagamento IS 'DEPRECATED: replaced by forma_pagamento_id; retained for backward compatibility';
CREATE INDEX IF NOT EXISTS financeiro_recebimentos_competencia_idx ON public.financeiro_recebimentos(clinica_id,competencia); CREATE INDEX IF NOT EXISTS financeiro_pagamentos_competencia_idx ON public.financeiro_pagamentos(clinica_id,competencia);

UPDATE public.financeiro_recebimentos SET competencia=date_trunc('month',vencimento)::date,valor_bruto=valor,valor_liquido=valor,valor_pago=CASE WHEN status='pago' THEN valor ELSE 0 END WHERE competencia IS NULL OR valor_bruto IS NULL;
UPDATE public.financeiro_pagamentos SET competencia=date_trunc('month',vencimento)::date,valor_bruto=valor,valor_liquido=valor,valor_pago=CASE WHEN status='pago' THEN valor ELSE 0 END WHERE competencia IS NULL OR valor_bruto IS NULL;
INSERT INTO public.contas_financeiras(clinica_id,unidade_id,nome,tipo) SELECT c.id,u.id,'Caixa principal','caixa' FROM public.clinicas c LEFT JOIN LATERAL(SELECT id FROM public.unidades WHERE clinica_id=c.id ORDER BY created_at LIMIT 1)u ON true ON CONFLICT DO NOTHING;
INSERT INTO public.formas_pagamento(clinica_id,nome,tipo,prazo_recebimento_dias,parcelamento_maximo) SELECT c.id,v.nome,v.tipo,v.prazo,v.parcelas FROM public.clinicas c CROSS JOIN(VALUES('Dinheiro','dinheiro',0,1),('PIX','pix',0,1),('Cartão de débito','debito',1,1),('Cartão de crédito','credito',30,12),('Boleto','boleto',2,12),('Convênio','convenio',30,1),('Plano interno','plano_interno',0,48))v(nome,tipo,prazo,parcelas) ON CONFLICT DO NOTHING;
UPDATE public.financeiro_recebimentos r SET forma_pagamento_id=f.id FROM public.formas_pagamento f WHERE f.clinica_id=r.clinica_id AND lower(f.nome)=lower(r.forma_pagamento) AND r.forma_pagamento_id IS NULL;
INSERT INTO public.plano_contas(clinica_id,nome,tipo,codigo,natureza) SELECT c.id,v.nome,v.tipo::public.conta_tipo,v.codigo,v.natureza FROM public.clinicas c CROSS JOIN(VALUES('Receitas','receita','1','receita'),('Deduções e impostos','despesa','2','deducao'),('Custos variáveis','despesa','3','custo_variavel'),('Despesas fixas','despesa','4','despesa_fixa'),('Despesas financeiras','despesa','5','despesa_financeira'),('Investimentos','despesa','6','investimento'))v(nome,tipo,codigo,natureza) ON CONFLICT DO NOTHING;
UPDATE public.plano_contas p SET pai_id=g.id,natureza='receita' FROM public.plano_contas g WHERE g.clinica_id=p.clinica_id AND g.codigo='1' AND p.id<>g.id AND p.tipo='receita' AND p.pai_id IS NULL;
UPDATE public.plano_contas p SET pai_id=g.id,natureza=CASE WHEN lower(p.nome) LIKE '%imposto%' THEN 'deducao' WHEN lower(p.nome) LIKE '%material%' OR lower(p.nome) LIKE '%laborat%' OR lower(p.nome) LIKE '%comiss%' OR lower(p.nome) LIKE '%taxa%' THEN 'custo_variavel' ELSE 'despesa_fixa' END FROM public.plano_contas g WHERE g.clinica_id=p.clinica_id AND g.codigo='4' AND p.id<>g.id AND p.tipo='despesa' AND p.pai_id IS NULL;